//! Emoji data (generated by `build.rs`), search and lookup.
use std::{collections::HashMap, sync::OnceLock};

include!(concat!(env!("OUT_DIR"), "/emoji_data.rs"));

/// Display order: (id, title, icon emoji). Index 0 is the recents pseudo-category.
pub const CATEGORIES: [(&str, &str, &str); 9] = [
    ("recent", "Recently Used", "🕙"),
    ("smileys-people", "Smileys & People", "🙂"),
    ("animals-nature", "Animals & Nature", "🐯"),
    ("food-drink", "Food & Drink", "🍔"),
    ("activities", "Activities", "⚽"),
    ("travel-places", "Travel & Places", "✈️"),
    ("objects", "Objects", "💡"),
    ("symbols", "Symbols", "⁉️"),
    ("flags", "Flags", "🇺🇳"),
];

/// Emoji indices of a category (index into `CATEGORIES`, never 0).
pub fn in_category(category: usize) -> &'static [u16] {
    BY_CATEGORY[category - 1]
}

/// Case-insensitive substring match over the name and keywords.
pub fn search(query: &str) -> Vec<usize> {
    if query.contains('\u{1}') {
        return Vec::new();
    }
    let query = query.to_lowercase();
    EMOJIS
        .iter()
        .enumerate()
        .filter(|(_, e)| e.terms.contains(&query))
        .map(|(i, _)| i)
        .collect()
}

pub fn is_tone_modifier(c: char) -> bool {
    ('\u{1F3FB}'..='\u{1F3FF}').contains(&c)
}

pub fn strip_tone(s: &str) -> String {
    s.chars().filter(|c| !is_tone_modifier(*c)).collect()
}

fn normalize(s: &str) -> String {
    s.chars()
        .filter(|c| !is_tone_modifier(*c) && *c != '\u{FE0F}')
        .collect()
}

/// Find an emoji by character, ignoring skin tone and the emoji-presentation selector.
pub fn find_by_char(ch: &str) -> Option<usize> {
    static INDEX: OnceLock<HashMap<String, usize>> = OnceLock::new();
    let index = INDEX.get_or_init(|| {
        let mut map = HashMap::with_capacity(EMOJIS.len());
        for (i, e) in EMOJIS.iter().enumerate() {
            map.entry(normalize(e.ch)).or_insert(i);
        }
        map
    });
    index.get(&normalize(ch)).copied()
}

/// The character to show/copy for the chosen skin tone (0 = default).
pub fn char_for(index: usize, tone: usize) -> &'static str {
    let e = &EMOJIS[index];
    if tone > 0 && e.has_tones && !e.tones[tone - 1].is_empty() {
        e.tones[tone - 1]
    } else {
        e.ch
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn search_finds_by_name_and_keyword() {
        let hits = search("grinning");
        assert!(hits.iter().any(|&i| EMOJIS[i].ch == "😀"));
        assert!(!search("brazil").is_empty());
        assert!(search("zzzzqqqq").is_empty());
    }

    #[test]
    fn search_does_not_cross_term_boundaries() {
        assert!(search("face\u{1}").is_empty());
    }

    #[test]
    fn find_ignores_tone_and_variation_selector() {
        assert!(find_by_char("❤").is_some());
        assert_eq!(find_by_char("👍🏽"), find_by_char("👍"));
    }

    #[test]
    fn tones_are_linked() {
        let thumbs = find_by_char("👍").unwrap();
        // The base glyph carries the emoji-presentation selector (U+FE0F), as in the CSV.
        assert_eq!(strip_tone(char_for(thumbs, 0)).trim_end_matches('\u{FE0F}'), "👍");
        assert_eq!(char_for(thumbs, 3), "👍🏽");
    }

    #[test]
    fn every_category_has_emoji() {
        for (c, category) in CATEGORIES.iter().enumerate().skip(1) {
            assert!(!in_category(c).is_empty(), "{}", category.0);
        }
    }
}
